package net.zartra.gui;
import org.bukkit.Bukkit;import org.bukkit.entity.Player;import java.util.regex.*;
final class PlaceholderService {private final VariableStore variables;PlaceholderService(){this(new VariableStore());}PlaceholderService(VariableStore v){variables=v;}String replace(Player p,MenuDefinition m,String input){String r=input==null?"":input.replace("%menu%",m==null?"":m.title).replace("%menu_id%",m==null?"":m.id).replace("%server%",Bukkit.getServerName());if(p!=null)r=r.replace("%player%",p.getName()).replace("%player_name%",p.getName()).replace("%player_uuid%",p.getUniqueId().toString()).replace("%display_name%",p.getDisplayName()).replace("%world%",p.getWorld().getName()).replace("%x%",String.valueOf(p.getLocation().getBlockX())).replace("%y%",String.valueOf(p.getLocation().getBlockY())).replace("%z%",String.valueOf(p.getLocation().getBlockZ())).replace("%level%",String.valueOf(p.getLevel())).replace("%health%",String.valueOf(p.getHealth())).replace("%max_health%",String.valueOf(p.getMaxHealth())).replace("%food%",String.valueOf(p.getFoodLevel())).replace("%gamemode%",p.getGameMode().name()).replace("%online%",String.valueOf(Bukkit.getOnlinePlayers().size())).replace("%max_players%",String.valueOf(Bukkit.getMaxPlayers()));r=variables(r,p,m);if(Bukkit.getPluginManager().getPlugin("PlaceholderAPI")!=null)try{Class<?> c=Class.forName("me.clip.placeholderapi.PlaceholderAPI");java.lang.reflect.Method x=c.getMethod("setPlaceholders",Player.class,String.class);r=(String)x.invoke(null,p,r);}catch(Exception ignored){}return r;}
 private String variables(String input,Player p,MenuDefinition m){Matcher q=Pattern.compile("%var:([A-Za-z]+:[A-Za-z0-9_.-]+)%").matcher(input);StringBuffer out=new StringBuffer();while(q.find()){String value=p==null?null:variables.resolve(p.getUniqueId(),m==null?null:m.id,q.group(1));q.appendReplacement(out,Matcher.quoteReplacement(value==null?"":value));}q.appendTail(out);return out.toString();}
}